def is_prime(n):
    # ตรวจสอบว่า n เป็นจำนวนเต็มบวกหรือไม่
    if n <= 1:
        return False
    # n = 2 เป็นจำนวนเฉพาะ
    if n == 2:
        return True
    # n = 0 หรือ 1 ไม่ใช่จำนวนเฉพาะ
    if n <= 1:
        return False

    # ตรวจสอบหารด้วยจำนวนเต็มตั้งแต่ 2 ถึง sqrt(n)
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True
